763	async function loadStore(file: string): Promise<Store> {
764	  let text: string;
765	  try {
766	    text = await readFile(file, 'utf8');
767	  } catch (err) {
768	    if ((err as NodeJS.ErrnoException).code === 'ENOENT') return emptyStore();
769	    throw new BizError(`无法读取数据文件 ${file}: ${(err as Error).message}`);
770	  }
771	  let raw: unknown;
772	  try {
773	    raw = JSON.parse(text);
774	  } catch (err) {
775	    throw new BizError(
776	      `数据文件 ${file} 已损坏，不是合法 JSON：${(err as Error).message}（原文件已保留，未当作空数据覆盖）`,
777	    );
778	  }
779	  return validateStore(raw, file);
780	}
