782	// 先完整写入临时文件，再原子改名；任何失败都不触碰原文件
783	async function saveStore(file: string, store: Store): Promise<void> {
784	  let json: string;
785	  try {
786	    json = JSON.stringify(store, null, 2) + '\n';
787	  } catch (err) {
788	    throw new BizError(`序列化数据失败：${(err as Error).message}（原文件已保留）`);
789	  }
790	  const tmp = `${file}.${process.pid}.tmp`;
791	  try {
792	    await writeFile(tmp, json, {encoding: 'utf8', flag: 'wx'});
793	    await rename(tmp, file);
794	  } catch (err) {
795	    await unlink(tmp).catch(() => {});
796	    throw new BizError(`保存数据文件 ${file} 失败：${(err as Error).message}（原文件已保留）`);
797	  }
798	}
