813	// 校验请求中的资源标识：去重、检查存在性；返回按标识排序的集合
814	function resolveResourceIds(store: Store, rawIds: string[]): string[] {
815	  const problems: string[] = [];
816	  const seen = new Set<string>();
817	  const dupes: string[] = [];
818	  for (const id of rawIds) {
819	    if (seen.has(id)) {
820	      if (!dupes.includes(id)) dupes.push(id);
821	    }
822	    seen.add(id);
823	  }
824	  if (dupes.length > 0) problems.push(`资源重复指定: ${dupes.join('、')}`);
825	
826	  const unknown = [...seen].filter((id) => !store.resources.some((r) => r.id === id)).sort();
827	  if (unknown.length > 0) problems.push(`未知资源标识: ${unknown.join('、')}`);
828	
829	  if (problems.length > 0) throw new BizError(problems.join('\n'));
830	  return [...seen].sort();
831	}
