938	// 与“已预约”记录求冲突：共同资源且时间重叠（左闭右开）；可排除自身
939	function findConflicts(
940	  store: Store,
941	  ids: string[],
942	  startMin: number,
943	  endMin: number,
944	  excludeBookingId?: string,
945	): Conflict[] {
946	  const wanted = new Set(ids);
947	  const conflicts: Conflict[] = [];
948	  for (const b of store.bookings) {
949	    if (b.status !== 'active') continue;
950	    if (excludeBookingId !== undefined && b.id === excludeBookingId) continue;
951	    const bStart = parseDateTime(b.start, '预约开始时间');
952	    const bEnd = parseDateTime(b.end, '预约结束时间');
953	    const overlap = bStart < endMin && startMin < bEnd;
954	    if (!overlap) continue;
955	    const shared = b.resourceIds.filter((id) => wanted.has(id)).sort();
956	    if (shared.length > 0) conflicts.push({booking: b, shared});
957	  }
958	  conflicts.sort((a, b) => a.booking.id.localeCompare(b.booking.id));
959	  return conflicts;
960	}
961	
962	function assertNoConflicts(conflicts: Conflict[], store: Store): void {
963	  if (conflicts.length === 0) return;
964	  const lines = conflicts.map(
965	    (c) => `- ${c.booking.id}：共同资源 ${formatResourceIds(store, c.shared)}`,
966	  );
967	  throw new BizError(`预约与以下预约冲突（共同资源时间重叠）：\n${lines.join('\n')}`);
968	}
