980	function splitGlobalArgs(argv: string[]): GlobalArgs {
981	  const result: GlobalArgs = {dataFile: DEFAULT_DATA_FILE, help: false, rest: []};
982	  for (let i = 0; i < argv.length; i++) {
983	    const a = argv[i];
984	    if (a === '-h' || a === '--help') {
985	      result.help = true;
986	    } else if (a === '--data') {
987	      const v = argv[++i];
988	      if (v === undefined) throw new UsageError('选项 --data 缺少数据文件路径');
989	      result.dataFile = v;
990	    } else if (a.startsWith('--data=')) {
991	      result.dataFile = a.slice('--data='.length);
992	      if (result.dataFile === '') throw new UsageError('选项 --data 缺少数据文件路径');
993	    } else {
994	      result.rest.push(a);
