1000	interface ParsedFlags {
1001	  values: Map<string, string[]>;
1002	  positionals: string[];
1003	}
1004	
1005	// 子命令选项解析：allowed 中列出的选项均需带值；multi 中的选项可重复
1006	function parseFlags(args: string[], allowed: string[], multi: string[] = []): ParsedFlags {
1007	  const allowedSet = new Set(allowed);
1008	  const multiSet = new Set(multi);
1009	  const values = new Map<string, string[]>();
1010	  const positionals: string[] = [];
1011	
1012	  const takeValue = (key: string, inline: string | undefined, index: number): [string, number] => {
1013	    if (inline !== undefined) return [inline, index];
1014	    const v = args[index + 1];
1015	    if (v === undefined || v.startsWith('-')) {
1016	      throw new UsageError(`选项 --${key} 缺少值`);
1017	    }
1018	    return [v, index + 1];
1019	  };
1020	
1021	  for (let i = 0; i < args.length; i++) {
1022	    const a = args[i];
1023	    if (a.startsWith('--')) {
1024	      let key: string;
1025	      let inline: string | undefined;
1026	      const eq = a.indexOf('=');
1027	      if (eq >= 0) {
1028	        key = a.slice(2, eq);
1029	        inline = a.slice(eq + 1);
1030	      } else {
1031	        key = a.slice(2);
1032	      }
1033	      if (!allowedSet.has(key)) throw new UsageError(`未知选项: --${key}`);
1034	      let v: string;
1035	      [v, i] = takeValue(key, inline, i);
1036	      if (v === '') throw new UsageError(`选项 --${key} 的值不能为空`);
1037	      if (!multiSet.has(key) && values.has(key)) {
1038	        throw new UsageError(`选项 --${key} 只能指定一次`);
1039	      }
1040	      const list = values.get(key) ?? [];
1041	      list.push(v);
1042	      values.set(key, list);
1043	    } else if (a.startsWith('-') && a !== '-') {
1044	      throw new UsageError(`未知参数: ${a}`);
1045	    } else {
1046	      positionals.push(a);
1047	    }
1048	  }
1049	  return {values, positionals};
1050	}
1051	
1052	function requireFlag(values: Map<string, string[]>, key: string): string {
1053	  const v = values.get(key)?.[0];
1054	  if (v === undefined) throw new UsageError(`缺少必需选项 --${key}`);
1055	  return v;
1056	}
