1157	  if (booking.status === 'cancelled') {
1158	    throw new BizError(`预约 ${id} 已取消，不能改期`);
1159	  }
1160	
1161	  const hasTime = values.has('start') || values.has('end');
1162	  const hasResource = values.has('resource');
1163	  if (!hasTime && !hasResource) {
1164	    throw new BizError('未指定任何改动：请提供 --start/--end 修改时间，或 --resource 替换资源（可同时提供）');
1165	  }
1166	
1167	  const startRaw = values.get('start')?.[0] ?? booking.start;
1168	  const endRaw = values.get('end')?.[0] ?? booking.end;
1169	  const startMin = parseDateTime(startRaw, '预约开始时间');
1170	  const endMin = parseDateTime(endRaw, '预约结束时间');
1171	  if (endMin <= startMin) {
1172	    throw new BizError(`预约结束时间必须晚于开始时间（开始: ${startRaw}，结束: ${endRaw}），允许跨日`);
1173	  }
1174	
1175	  let ids: string[] = booking.resourceIds;
1176	  if (hasResource) {
1177	    const resourceArgs = values.get('resource')!;
1178	    ids = resolveResourceIds(store, resourceArgs);
1179	  }
1180	
1181	  assertOpenCoverage(store, ids, startMin, endMin);
1182	  // 改期检查排除自身
1183	  assertNoConflicts(findConflicts(store, ids, startMin, endMin, id), store);
