1233	// 清单结构（与数据文件无关的纯类型校验）；返回逐项原始记录
1234	function parseManifestShape(raw: unknown, file: string): Array<Record<string, unknown>> {
1235	  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) {
1236	    throw new BizError(`改期清单 ${file} 内容非法：顶层必须是对象，形如 {"items": [...]}`);
1237	  }
1238	  const o = raw as Record<string, unknown>;
1239	  for (const k of Object.keys(o)) {
1240	    if (k !== 'items') throw new BizError(`改期清单 ${file} 内容非法：存在未知字段 “${k}”，只允许 items`);
1241	  }
1242	  if (!Array.isArray(o.items)) {
1243	    throw new BizError(`改期清单 ${file} 内容非法：items 必须是非空数组`);
1244	  }
1245	  const items = o.items as unknown[];
1246	  if (items.length === 0) throw new BizError(`改期清单 ${file} 为空：items 至少包含一项改期安排`);
1247	
1248	  const problems: string[] = [];
1249	  const records: Array<Record<string, unknown> | null> = [];
1250	  items.forEach((it, idx) => {
1251	    const at = `第 ${idx + 1} 项`;
1252	    if (typeof it !== 'object' || it === null || Array.isArray(it)) {
1253	      problems.push(`${at} 必须是对象`);
1254	      records.push(null);
1255	      return;
1256	    }
1257	    const rec = it as Record<string, unknown>;
1258	    for (const k of Object.keys(rec)) {
1259	      if (k !== 'bookingId' && k !== 'start' && k !== 'end' && k !== 'resourceIds') {
1260	        problems.push(`${at} 存在未知字段 “${k}”（只允许 bookingId、start、end、resourceIds）`);
1261	      }
1262	    }
1263	    if (typeof rec.bookingId !== 'string' || rec.bookingId === '') {
1264	      problems.push(`${at} 的 bookingId 必须是非空字符串`);
1265	    }
1266	    if (typeof rec.start !== 'string' || rec.start === '') {
1267	      problems.push(`${at} 的 start 必须是 YYYY-MM-DDTHH:mm 形式的非空字符串`);
1268	    }
1269	    if (typeof rec.end !== 'string' || rec.end === '') {
1270	      problems.push(`${at} 的 end 必须是 YYYY-MM-DDTHH:mm 形式的非空字符串`);
1271	    }
1272	    if (!Array.isArray(rec.resourceIds)) {
1273	      problems.push(`${at} 的 resourceIds 必须是非空数组（完整目标资源集合，整体替换原集合）`);
1274	    } else {
1275	      if (rec.resourceIds.length === 0) problems.push(`${at} 的 resourceIds 不能为空：资源集合整体替换，至少一个资源`);
1276	      rec.resourceIds.forEach((rid, j) => {
1277	        if (typeof rid !== 'string' || rid === '') {
1278	          problems.push(`${at}.resourceIds[${j}] 必须是非空资源标识字符串`);
1279	        }
1280	      });
1281	    }
1282	    records.push(rec);
1283	  });
1284	  if (problems.length > 0) {
1285	    throw new BizError(`改期清单 ${file} 内容非法，整批拒绝：\n${problems.map((p) => `- ${p}`).join('\n')}`);
1286	  }
1287	  return records as Array<Record<string, unknown>>;
1288	}
