Wait — careful with folding: a line starting with space/tab when lines.length === 0 (file starts with folded line) → structural error.

Property line parse:

```ts
function parseContentLine(line: string): {name: string; params: string[]; value: string} {
  const colon = line.indexOf(':');
  if (colon < 0) throw structural;
  const head = line.slice(0, colon);
  const value = line.slice(colon + 1);
  const segs = head.split(';');
  const name = segs[0].toUpperCase();
  if (!/^[A-Za-z0-9-]+$/.test(segs[0]) ...) 
  const params = segs.slice(1);
  return {name, params, value};
