      case 'DTSTART': / 'DTEND': params check; parse floating time
      case 'DESCRIPTION': ignore
      case 'STATUS': if value.toUpperCase() === 'CANCELLED' → bad('取消事件')
      case 'RRULE': case 'RDATE': case 'EXDATE': case 'EXRULE': case 'RECURRENCE-ID':
        bad('重复相关属性')
      default: ignore
    }
  }
}
