### Import command

```ts
async function cmdImportIcal(args: string[]): Promise<void> {
  const {values, positionals} = parseFlags(args, ['resource'], ['resource']);
  if (positionals.length !== 1) throw new UsageError('用法: import-ical <iCalendar 文件> --resource <标识> [--resource <标识> ...]');
  const resourceArgs = values.get('resource');
  if (!resourceArgs || resourceArgs.length === 0) throw new UsageError('至少需要一个 --resource');
  const icalFile = positionals[0];

  const file = activeDataFile;
  const store = await loadStore(file);
  const ids = resolveResourceIds(store, resourceArgs); // sorted

  // read file
  let text: string;
  try { text = await readFile(icalFile, 'utf8'); }
  catch (err) { throw new BizError(`无法读取 iCalendar 文件 ${icalFile}: ...`); }
  const events = parseIcal(text, icalFile); // at least one VEVENT guaranteed

  // classify replay vs new; mismatch → collect and reject whole batch
  const importByUid = new Map(store.imports.map((r) => [r.uid, r]));
  const problems: string[] = [];
  interface Item { ev: IcalEvent; index: number; replay?: ImportRec }
  const items: Item[] = events.map((ev, index) => {
    const rec = importByUid.get(ev.uid);
    if (rec) {
      const sameTime = rec.start === ev.startRaw && rec.end === ev.endRaw;
      const sameRes = rec.resourceIds.length === ids.length && rec.resourceIds.every((x, j) => x === ids[j]);
      if (!sameTime || !sameRes) {
        problems.push(`第 ${index+1} 项 UID “${ev.uid}”：与首次导入记录不一致（首次 ${rec.start} → ${rec.end}，资源 ${rec.resourceIds.join('、')}；本次 ${ev.startRaw} → ${ev.endRaw}，资源 ${ids.join('、')}），相同 UID 的时间或资源集合不同即整批拒绝`);
      }
      return {ev, index, replay: rec};
    }
    return {ev, index};
  });
  if (problems.length > 0) throw new BizError(`iCalendar 导入被拒绝：...\n${problems...}`);
```

